example.chain:
use function Phit\fit_logistic;

// Hours of study and passing an exam, for eight students.
$fit = fit_logistic(
    x: [[2.0], [3.5], [1.0], [4.0], [2.5], [5.0], [1.5], [3.0]],
    y: [0, 1, 0, 1, 1, 1, 0, 0],
);

foreach (['(Intercept)', 'hours'] as $j => $term) {
    printf("%-12s %8.4f  (SE %.4f, p = %.3f)\n", $term, $fit['coefficients'][$j], $fit['std_errors'][$j], $fit['p_values'][$j]);
}
echo function_exists('Phit\fit_logistic') && ! extension_loaded('phit') ? "fitted by phit-polyfill\n" : "fitted by the phit extension\n";

example.pipe:
use function Phit\fit_logistic;

// Hours of study and passing an exam, for eight students.
$fit = fit_logistic(
    x: [[2.0], [3.5], [1.0], [4.0], [2.5], [5.0], [1.5], [3.0]],
    y: [0, 1, 0, 1, 1, 1, 0, 0],
);

echo ['(Intercept)', 'hours'] |>
    (fn (array $terms) => array_map(
        fn (string $term, int $j) => sprintf("%-12s %8.4f  (SE %.4f, p = %.3f)\n", $term, $fit['coefficients'][$j], $fit['std_errors'][$j], $fit['p_values'][$j]),
        $terms, array_keys($terms))) |>
    implode(...);
echo function_exists('Phit\fit_logistic') && ! extension_loaded('phit') ? "fitted by phit-polyfill\n" : "fitted by the phit extension\n";
